import{_ as o,o as t,c as r,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"市场准则","description":"","frontmatter":{},"headers":[],"relativePath":"09_books/巴菲特之道/准则/04_市场准则.md","filePath":"09_books/巴菲特之道/准则/04_市场准则.md"}'),l={name:"09_books/巴菲特之道/准则/04_市场准则.md"};function n(i,a,s,h,p,c){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="市场准则" tabindex="-1">市场准则 <a class="header-anchor" href="#市场准则" aria-label="Permalink to &quot;市场准则&quot;">​</a></h1><p>市场准则关注的是买入时机和价格，是价值投资的关键环节。</p><h2 id="两大市场准则" tabindex="-1">两大市场准则 <a class="header-anchor" href="#两大市场准则" aria-label="Permalink to &quot;两大市场准则&quot;">​</a></h2><h3 id="_1-安全边际" tabindex="-1">1. 安全边际 <a class="header-anchor" href="#_1-安全边际" aria-label="Permalink to &quot;1. 安全边际&quot;">​</a></h3><blockquote><p><strong>&quot;安全边际是投资的本质。&quot;</strong></p></blockquote><p>安全边际意味着你买入的价格要显著低于公司的内在价值，这样即使判断出错也能避免重大损失。</p><p><strong>核心要点：</strong></p><ul><li>买入价格 &lt; 内在价值的50%</li><li>为判断失误留出缓冲</li><li>越高越好</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/safety-margin">安全边际</a></p><hr><h3 id="_2-股票市值" tabindex="-1">2. 股票市值 <a class="header-anchor" href="#_2-股票市值" aria-label="Permalink to &quot;2. 股票市值&quot;">​</a></h3><blockquote><p><strong>&quot;关注的是公司价值，而非股价。&quot;</strong></p></blockquote><p>市值代表了公司在公开市场的定价，但内在价值才是真正重要的。</p><p><strong>核心要点：</strong></p><ul><li>市值应与公司长期价值相匹配</li><li>避免过度关注短期股价波动</li><li>长期持有优质公司</li></ul><p><strong>相关阅读：</strong> <a href="/search?q=市场先生">市场先生</a></p><hr><h2 id="安全边际的计算方法" tabindex="-1">安全边际的计算方法 <a class="header-anchor" href="#安全边际的计算方法" aria-label="Permalink to &quot;安全边际的计算方法&quot;">​</a></h2><p>巴菲特使用多种方法评估<a href="/02_concepts/intrinsic-value">内在价值</a>：</p><ol><li><strong>现金流折现法</strong></li><li><strong>清算价值法</strong></li><li><strong>可比公司法</strong></li></ol><blockquote><p><strong>&quot;用合理的价格买入优质公司，而不是用便宜的价格买入平庸公司。&quot;</strong></p></blockquote><hr><h2 id="何时买入" tabindex="-1">何时买入？ <a class="header-anchor" href="#何时买入" aria-label="Permalink to &quot;何时买入？&quot;">​</a></h2><p>巴菲特的买入时机：</p><ul><li><strong>市场恐慌时</strong>：1987年股灾、2008年金融危机</li><li><strong>公司暂时性困难时</strong></li><li><strong>股价大幅低于内在价值时</strong></li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/contrarian">逆向思维</a></p><hr><h2 id="案例-华盛顿邮报" tabindex="-1">案例：华盛顿邮报 <a class="header-anchor" href="#案例-华盛顿邮报" aria-label="Permalink to &quot;案例：华盛顿邮报&quot;">​</a></h2><p>1973年巴菲特买入华盛顿邮报，正是因为：</p><ul><li>安全边际：股价远低于内在价值</li><li>公司质地优秀</li><li>长期持有获得丰厚回报</li></ul><p><strong>相关阅读：</strong> <a href="/03_companies/华盛顿邮报">华盛顿邮报</a></p>',31)])])}const d=o(l,[["render",n]]);export{u as __pageData,d as default};
